import React, {useEffect,useMemo,useRef, useState} from 'react';
import {fixture} from './fixture.ts';
import {inventoryFor, scenarios, type Scenario} from './scenarios.ts';
import {auditInventory} from './audit.ts';
import {auditCsv,safeCsvCell} from './audit-export.ts';
import {filterAudit,type AuditStatus} from './audit-filter.ts';
import {compareScenarios} from './compare.ts';
import {triageFindings,ruleRisk,type RiskFilter,type FindingSort} from './triage.ts';
import {reviewPlan,planMarkdown} from './plan.ts';
import {scan, type Finding, type Inventory} from './scanner.ts';
import {parseInventory} from './import.ts';
import {explainEstimate} from './estimate.ts';
import {ruleCoverage} from './coverage.ts';
import {inputHealth} from './input-health.ts';
import {candidateTags,candidateAllocation} from './allocation.ts';
import {reviewGates} from './review-gate.ts';
import {reviewPriority} from './review-priority.ts';
import {rateSensitivity} from './rate-sensitivity.ts';
import {auditTag} from './tag-audit.ts';
import {inventoryDiff,inventoryDiffReport} from './inventory-diff.ts';
import {diffAnalysis} from './diff-analysis.ts';
import {reviewChecks,checklistProgress,type CheckId} from './checklist.ts';
import {stageCounts,filterByStage,type ReviewStage} from './review-stage.ts';
import {findingsCsv} from './findings-export.ts';
import {nextEvidence,auditGaps} from './audit-next.ts';
import {metricEvidence} from './metric-evidence.ts';
import {rateLab,type RateKey} from './rate-lab.ts';
import {comparisonFingerprint,verifiedComparison} from './comparison-state.ts';
import {reviewSession,restoreReviewSession} from './review-session.ts';
import {LiveEvidence} from './live-evidence.tsx';
import {TrueForgeRun} from './trueforge-run.tsx';

type Decision = 'approved' | 'kept';

const money = (n:number) => '$' + n.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
const icon:Record<Finding['kind'],string> = {'volume':'◫','ipv4':'◎','instance':'▣','load-balancer':'⌁','snapshot':'▤'};
const label:Record<Finding['kind'],string> = {'volume':'EBS / STORAGE','ipv4':'NETWORK / IPV4','instance':'EC2 / COMPUTE','load-balancer':'ELB / ROUTING','snapshot':'BACKUP / SNAPSHOT'};
const recommendation = (f:Finding) => f.recommendation;
const Glyph = ({name,size=21}:{name:string;size?:number}) => {
 const common={width:size,height:size,viewBox:'0 0 24 24',fill:'none',stroke:'currentColor',strokeWidth:1.65,strokeLinecap:'round' as const,strokeLinejoin:'round' as const,'aria-hidden':true as const};
 if(name==='instance') return <svg {...common}><rect x="4" y="4" width="16" height="16" rx="3"/><path d="M8 9h8M8 13h5M8 17h8"/></svg>;
 if(name==='volume') return <svg {...common}><rect x="4" y="5" width="16" height="14" rx="3"/><path d="M4 11h16M8 15h.01M12 15h.01"/></svg>;
 if(name==='ipv4') return <svg {...common}><circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c-5 5-5 13 0 18M12 3c5 5 5 13 0 18"/></svg>;
 if(name==='load-balancer') return <svg {...common}><rect x="2" y="3" width="6" height="5" rx="1"/><rect x="16" y="3" width="6" height="5" rx="1"/><rect x="9" y="16" width="6" height="5" rx="1"/><path d="M5 8v4h14V8M12 12v4"/></svg>;
 return <svg {...common}><rect x="4" y="5" width="16" height="15" rx="2"/><path d="M8 4v3M16 4v3M4 10h16M8 14h8M8 17h5"/></svg>;
};
function App(){
  const [scenario,setScenario]=useState<Scenario>('baseline');
  const [localInventory,setLocalInventory]=useState<Inventory|null>(null);
  const [importMessage,setImportMessage]=useState('');
  const sourceName=localInventory?'Local JSON (unverified)':scenarios[scenario].title;
  const inputInventory=localInventory||inventoryFor(scenario);
  const [jsonText,setJsonText]=useState('');
  const importText=()=>{try{if(jsonText.length>1_000_000)throw Error('Paste under 1 MB of JSON.');const data=parseInventory(JSON.parse(jsonText));setLocalInventory(data);setImportMessage('Loaded pasted JSON locally. No cloud connection or upload.')}catch(e){setLocalInventory(null);setImportMessage(e instanceof Error?e.message:'Could not parse this JSON.')}};
  const [findings,setFindings]=useState<Finding[]>(()=>scan(inventoryFor('baseline')));
  const [scanCount,setScanCount]=useState(0);
  const runScan=()=>{setFindings(scan(inputInventory));setDecisions({});setNotes({});setChecked({});setReviewJson('');setReviewRestoreMessage('');setComparisonInventory(null);setComparedAgainst('');setStages({});setStageFilter('all');setLastDecision(null);setAuditQuery('');setAuditStatus('all');setSelected(null);setFilter('all');setRiskFilter('all');setScanCount(n=>n+1);setScene('dashboard');window.scrollTo({top:0,behavior:'smooth'});};
  const [scene,setScene]=useState<'landing'|'setup'|'dashboard'|'agent'>(new URLSearchParams(window.location.search).get('view')==='agent'?'agent':new URLSearchParams(window.location.search).get('view')==='dashboard'?'dashboard':new URLSearchParams(window.location.search).get('view')==='setup'?'setup':'landing');
  const [decisions,setDecisions]=useState<Record<string,Decision>>({});
  const [selected,setSelected]=useState<string|null>(null);
  const closeRef=useRef<HTMLButtonElement|null>(null);
  const priorFocus=useRef<HTMLElement|null>(null);
  const openDetail=(id:string)=>{priorFocus.current=document.activeElement as HTMLElement;setSelected(id)};
  const closeDetail=()=>{setSelected(null);setTimeout(()=>priorFocus.current?.focus(),0)};
  useEffect(()=>{if(selected)closeRef.current?.focus()},[selected]);
  const [filter,setFilter]=useState<'all'|'review'|'approved'|'kept'>('all');
  const [query,setQuery]=useState('');
  const [category,setCategory]=useState('all');
  const [sort,setSort]=useState<FindingSort>('cost-desc');
  const [riskFilter,setRiskFilter]=useState<RiskFilter>('all');
  const [monthlyTarget,setMonthlyTarget]=useState(50);
  const [itemReviewThreshold,setItemReviewThreshold]=useState(20);
  const [notes,setNotes]=useState<Record<string,string>>({});
  const [reviewJson,setReviewJson]=useState('');
  const [reviewRestoreMessage,setReviewRestoreMessage]=useState('');
  const [checked,setChecked]=useState<Record<string,CheckId[]>>({});
  const [stages,setStages]=useState<Record<string,ReviewStage>>({});
  const [stageFilter,setStageFilter]=useState<ReviewStage|'all'>('all');
  const [showInsights,setShowInsights]=useState(false);
  const [showComparison,setShowComparison]=useState(false);
  const [showAudit,setShowAudit]=useState(false);
  const [auditQuery,setAuditQuery]=useState('');
  const [auditStatus,setAuditStatus]=useState<AuditStatus>('all');
  const [showPlan,setShowPlan]=useState(false);
  const [showCoverage,setShowCoverage]=useState(false);
  const [showAllocation,setShowAllocation]=useState(false);
  const [showPriority,setShowPriority]=useState(false);
  const [showSensitivity,setShowSensitivity]=useState(false);
  const [showLocalDiff,setShowLocalDiff]=useState(false);
  const [comparisonText,setComparisonText]=useState('');
  const [comparisonInventory,setComparisonInventory]=useState<Inventory|null>(null);
  const [comparedAgainst,setComparedAgainst]=useState('');
  const [comparisonError,setComparisonError]=useState('');
  const [ratePercent,setRatePercent]=useState(100);
  const [showRateLab,setShowRateLab]=useState(false);
  const [rateKey,setRateKey]=useState<RateKey>('t3MediumHour');
  const [trialRate,setTrialRate]=useState<number|null>(null);
  const [allocationKey,setAllocationKey]=useState('');
  const [lastDecision,setLastDecision]=useState<{id:string;prior?:Decision}|null>(null);
  const download=(name:string,data:string,type:string)=>{const blob=new Blob([data],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)};
  const exportReport=()=>download('nimbus-review.json',JSON.stringify({source:localInventory?'Local user-supplied JSON (unverified), no AWS connection':'Synthetic AWS-shaped fixture, not a live AWS account',capturedAt:inputInventory.capturedAt,region:inputInventory.region,assumptions:'Rough fixture rates; estimated candidate waste, not an AWS bill or verified saving',monthlyCandidateUsd:possible,monthlyApprovedUsd:projected,findings:findings.map(f=>({...f,decision:decisions[f.id]||'unreviewed',reviewNote:notes[f.id]||'',selfMarkedChecks:checked[f.id]||[],localReviewStage:stages[f.id]||'new'}))},null,2),'application/json');
  const exportCsv=()=>download('nimbus-sample-findings.csv',findingsCsv(findings,decisions,notes,stages,checked,sourceName),'text/csv');
  const projected=useMemo(()=>findings.filter(f=>decisions[f.id]==='approved').reduce((n,f)=>n+f.estimatedMonthlyUsd,0),[decisions,findings]);
  const possible=findings.reduce((n,f)=>n+f.estimatedMonthlyUsd,0);
  const reviewed=Object.keys(decisions).length;
  const visible=triageFindings(filterByStage(findings.filter(f=>(filter==='all'||(filter==='review'?!decisions[f.id]:decisions[f.id]===filter))&&(category==='all'||f.kind===category)&&(`${f.title} ${f.resourceId} ${f.explanation} ${f.kind}`.toLowerCase().includes(query.trim().toLowerCase()))),stages,stageFilter),riskFilter,sort);
  const audit=auditInventory(inputInventory,findings);
  const auditVisible=filterAudit(audit,auditQuery,auditStatus);
  const gaps=auditGaps(audit);
  const plan=reviewPlan(findings,decisions);
  const checkProgress=checklistProgress(findings,checked);
  const restoreReview=()=>{try{const restored=restoreReviewSession(reviewJson,inputInventory,findings);setDecisions(restored.decisions);setNotes(restored.notes);setStages(restored.stages);setChecked(restored.checked);setLastDecision(null);setReviewRestoreMessage('Review restored locally for this exact scan. No AWS action was taken.')}catch(e){setReviewRestoreMessage(e instanceof Error?e.message:'Could not restore the review.')}};
  const stageProgress=stageCounts(findings,stages);
  const gates=reviewGates(findings,decisions,itemReviewThreshold);
  const priority=reviewPriority(findings,decisions);
  const sensitivity=rateSensitivity(inputInventory,ratePercent/100);
  const lab=rateLab(inputInventory,rateKey,trialRate??inputInventory.rates[rateKey]);
  const comparison=verifiedComparison(comparisonInventory,inputInventory,comparedAgainst);
  const diffDetails=comparison&&comparisonInventory?diffAnalysis(comparisonInventory,inputInventory):null;
  const compareText=()=>{try{if(comparisonText.length>1_000_000)throw Error('Paste under 1 MB of JSON.');const parsed=parseInventory(JSON.parse(comparisonText));inventoryDiff(parsed,inputInventory);setComparisonInventory(parsed);setComparedAgainst(comparisonFingerprint(inputInventory));setComparisonError('')}catch(e){setComparisonInventory(null);setComparedAgainst('');setComparisonError(e instanceof Error?e.message:'Invalid JSON.')}};
  const coverage=ruleCoverage(inputInventory);
  const health=inputHealth(inputInventory,new Date().toISOString());
  const tagKeys=candidateTags(inputInventory);
  const selectedTag=tagKeys.includes(allocationKey)?allocationKey:tagKeys[0];
  const allocation=selectedTag?candidateAllocation(inputInventory,findings,selectedTag):[];
  const tagQuality=selectedTag?auditTag(inputInventory,findings,selectedTag):null;
  const comparisons=compareScenarios();
  const breakdown=Object.entries(findings.reduce((out,f)=>({...out,[f.kind]:(out[f.kind]||0)+f.estimatedMonthlyUsd}),{} as Record<string,number>)).sort((a,b)=>b[1]-a[1]);
  const active=findings.find(f=>f.id===selected);
  const decide=(f:Finding,d:Decision)=>{setLastDecision({id:f.id,prior:decisions[f.id]});setDecisions(old=>({...old,[f.id]:d}))};
  const undo=()=>{if(!lastDecision)return;setDecisions(old=>{const copy={...old};if(lastDecision.prior)copy[lastDecision.id]=lastDecision.prior;else delete copy[lastDecision.id];return copy});setLastDecision(null)};
  if(scene==='agent') return <main className="agent-page"><header className="agent-nav"><button onClick={()=>setScene('landing')}>← Nimbus</button><span>NIMBUS / TRUEFORGE AGENT</span><span>LOCAL SERVER · READ-ONLY AWS TOOLS</span></header><section className="agent-intro"><span className="small-label">LIVE AGENT MODE / LOCAL SETUP REQUIRED</span><h1>Evidence first.<br/>Then ask.</h1><p>Run the saved Nimbus agent directly from this page. TrueForge owns the session, tool execution, sandbox, and streamed events; live AWS evidence is also available below for review.</p><p><a className="agent-open" href="http://localhost:8790" target="_blank" rel="noopener noreferrer">Open local TrueForge chat ↗</a></p><p>Requires a configured model, connector, and Daytona sandbox. TrueForge local mode has no login by default; keep it on localhost.</p></section><TrueForgeRun/><LiveEvidence/></main>;
  if(scene==='landing') return <Landing openAgent={()=>setScene('agent')} openDashboard={()=>{setScene('setup');window.scrollTo({top:0,behavior:'smooth'})}}/>;
  if(scene==='setup') return <Setup scenario={scenario} onScenario={s=>{setScenario(s);setLocalInventory(null);setImportMessage('')}} onImport={importText} jsonText={jsonText} onJsonText={setJsonText} importMessage={importMessage} localInventory={localInventory} onBack={()=>{setScene('landing');window.scrollTo({top:0,behavior:'smooth'})}} onRun={runScan}/>;
  return <main className="dashboard">
    <div className="ambient ambient-one"/><div className="ambient ambient-two"/>
    <header className="topbar"><button className="back-link" onClick={()=>setScene('landing')}>← Overview</button><div className="mark"><img className="brand-mascot dashboard-mascot" alt="" src="data:image/png;base64,"/><span><em>Nimbus</em></span></div><div className="top-right"><span className="demo-pill"><span className="pulse"/> {localInventory?'LOCAL JSON':'SAMPLE INVENTORY'}</span><span className="account">{localInventory?'PASTED JSON / ':'AWS-SHAPED FIXTURE / '}{inputInventory.accountId||'account not provided'} / {inputInventory.region}</span></div></header>
    <section className="hero"><div className="dash-cloud dash-cloud-one"/><div className="dash-cloud dash-cloud-two"/><div className="eyebrow"><span className="eyebrow-line"/> INVENTORY SCANNED <span className="eyebrow-index">02 / SCAN REPORT</span></div><h1>Find the leaks.<br/><span>Keep the control.</span></h1><div className="hero-foot"><p>{findings.length} findings computed from the {localInventory?'pasted JSON':'sample inventory'}. Open a resource to inspect the rule evidence, then choose what stays in your plan.</p><span className="scan-date">{localInventory?'LOCAL':'SAMPLE'} SCAN #{scanCount}<br/>{new Date(inputInventory.capturedAt).toLocaleDateString('en-US',{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'}).toUpperCase()}</span></div></section>
    <section className={'input-health '+(health.level==='fresh'?'':'input-health-warn')} aria-label="Input health and provenance"><div><span className="small-label">INPUT HEALTH / NOT ACCOUNT VERIFICATION</span><strong>{localInventory?'Pasted JSON, unverified':'Built-in synthetic example'}</strong><small>{health.resources} resource records · captured {inputInventory.capturedAt} · {health.ageDays===null?'capture age unknown':health.ageDays<0?'future timestamp':`${health.ageDays} days old`}</small></div><ul>{[...health.warnings,...health.rateWarnings].map(x=><li key={x}>{x}</li>)}</ul></section>
    <div className="scan-toolbar"><span>{sourceName} · Rules run: unattached storage, unused IPv4, low-use t3.medium compute, load balancers, snapshots</span><button onClick={runScan}>Run scan again ↻</button></div>
    <section className="savings" aria-label="Cost estimate"><div className="savings-main"><div className="small-label">POTENTIAL MONTHLY LEADS <span className="asterisk">*</span></div><div className="big-number">{money(possible)}<span>/mo</span></div><div className="savings-sub">Across {findings.length} possible findings <span>·</span> review before acting</div></div><div className="flow"><div className="flow-label">PROJECTED IMPACT <span>{reviewed}/{findings.length} REVIEWED</span></div><div className="flow-bar" role="progressbar" aria-label="Approved estimated savings" aria-valuemin={0} aria-valuemax={possible||1} aria-valuenow={projected}><div className="flow-filled" style={{width:`${possible?Math.min(100, projected/possible*100):0}%`}}/></div><div className="flow-values"><div><small>IF ALL WERE VALID</small><strong>{money(possible)}/mo</strong></div><span className="flow-arrow">→</span><div><small>APPROVED ESTIMATE</small><strong>{money(projected)}/mo</strong></div></div><p>Decisions update your in-browser plan only. No AWS resource or bill is changed.</p></div></section>
    <section className="findings-section"><div className="report-ribbon" aria-label="Scan summary"><div><span className="ribbon-spark">✳</span><strong>Five checks. One clear view.</strong><small>{sourceName} · computed locally · nothing removed</small></div><span className="ribbon-count">{String(findings.length).padStart(2,'0')} <em>leads to review</em></span></div><div className="section-head"><div><div className="small-label">THE FINDINGS</div><h2>What we noticed<span className="head-period">.</span></h2></div><span className="section-aside">EVIDENCE FIRST<br/>DECISIONS SECOND</span></div><div className="filters" role="group" aria-label="Filter findings">{(['all','review','approved','kept'] as const).map(x=><button key={x} onClick={()=>setFilter(x)} aria-pressed={filter===x} className={filter===x?'active':''}>{x==='review'?'To review':x==='kept'?'Denied':x[0].toUpperCase()+x.slice(1)} <span>{x==='all'?findings.length:x==='review'?findings.length-reviewed:Object.values(decisions).filter(y=>y===x).length}</span></button>)}</div><div className="review-stage-filter" aria-label="Filter local investigation stage"><span>INVESTIGATION / THIS BROWSER ONLY</span>{(["all","new","investigating","on-hold"] as const).map(x=><button key={x} className={stageFilter===x?"active":""} aria-pressed={stageFilter===x} onClick={()=>setStageFilter(x)}>{x==="all"?"All":x==="on-hold"?"On hold":x[0].toUpperCase()+x.slice(1)} {x==="all"?findings.length:stageProgress[x]}</button>)}</div><div className="report-tools" aria-label="Explore findings"><label>SEARCH RESOURCES<input type="search" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Resource ID, type, or evidence"/></label><label>SERVICE<select value={category} onChange={e=>setCategory(e.target.value)}><option value="all">All services</option>{Object.keys(label).map(k=><option key={k} value={k}>{label[k as Finding['kind']]}</option>)}</select></label><label>SORT<select value={sort} onChange={e=>setSort(e.target.value as typeof sort)}><option value="cost-desc">Highest estimate</option><option value="cost-asc">Lowest estimate</option><option value="name">Finding name</option><option value="risk">Rule caution first</option></select></label><label>RULE CAUTION<select value={riskFilter} onChange={e=>setRiskFilter(e.target.value as RiskFilter)}><option value="all">All levels</option><option value="critical">Critical</option><option value="high">High</option><option value="medium">Medium</option></select></label></div><p className="triage-disclaimer">Caution is assigned by the rule, not measured from your actual dependencies or business impact.</p><div className="result-line"><span>{visible.length} of {findings.length} findings shown</span><button onClick={()=>{setQuery('');setCategory('all');setSort('cost-desc');setRiskFilter('all');setStageFilter('all');setFilter('all')}}>Clear filters</button></div><div className="insights-actions"><button onClick={()=>setShowInsights(v=>!v)} aria-expanded={showInsights}>{showInsights?'Hide':'Explore'} cost picture ↗</button><button onClick={exportReport}>Download JSON report ↓</button><button onClick={exportCsv}>Download CSV ↓</button><button onClick={()=>setShowComparison(v=>!v)} aria-expanded={showComparison}>{showComparison?'Hide':'Compare'} sample situations ↗</button><button onClick={()=>setShowAudit(v=>!v)} aria-expanded={showAudit}>{showAudit?'Hide':'View'} scan audit ↗</button><button onClick={()=>setShowPlan(v=>!v)} aria-expanded={showPlan}>{showPlan?'Hide':'Open'} review plan ↗</button><button onClick={()=>setShowCoverage(v=>!v)} aria-expanded={showCoverage}>{showCoverage?'Hide':'See'} input coverage ↗</button><button onClick={()=>setShowAllocation(v=>!v)} aria-expanded={showAllocation}>{showAllocation?'Hide':'Group'} candidates by tag ↗</button><button onClick={()=>setShowPriority(v=>!v)} aria-expanded={showPriority}>{showPriority?'Hide':'See'} review queue ↗</button><button onClick={()=>setShowSensitivity(v=>!v)} aria-expanded={showSensitivity}>{showSensitivity?'Hide':'Test'} rate assumptions ↗</button><button onClick={()=>setShowRateLab(v=>!v)} aria-expanded={showRateLab}>{showRateLab?"Hide":"Test"} one input rate ↗</button><button onClick={()=>setShowLocalDiff(v=>!v)} aria-expanded={showLocalDiff}>{showLocalDiff?'Hide':'Compare'} local inputs ↗</button></div>{showComparison&&<section className="scenario-compare" aria-label="Compare synthetic sample situations"><div className="small-label">FOUR SYNTHETIC SITUATIONS / NOT ACCOUNT HISTORY</div><h3>See how the answer changes.</h3><p>Each card runs the same five rules on a different built-in fixture. These are separate examples, not before-and-after changes to an account, a savings forecast, or the result of your pasted JSON.</p><div className="compare-grid">{comparisons.map(item=><article key={item.scenario}><h4>{item.title}</h4><strong>{item.count} <span>leads</span></strong><b>{money(item.monthlyCandidateUsd)}/mo</b><p>{item.resourceIds.length?item.resourceIds.join(' · '):'No candidates'}</p><button onClick={()=>{setScenario(item.scenario);setComparisonInventory(null);setComparedAgainst('');setLocalInventory(null);setImportMessage('');setFindings(scan(inventoryFor(item.scenario)));setDecisions({});setNotes({});setChecked({});setReviewJson('');setReviewRestoreMessage('');setComparisonInventory(null);setComparedAgainst('');setStages({});setStageFilter('all');setLastDecision(null);setSelected(null);setFilter('all');setRiskFilter('all');setAuditQuery('');setAuditStatus('all');setScanCount(n=>n+1);window.scrollTo({top:0,behavior:'smooth'})}}>Inspect this sample ↗</button></article>)}</div></section>}{showLocalDiff&&<section className="local-diff-panel" aria-label="Compare local inventories"><div className="small-label">TWO LOCAL INVENTORIES / NO AWS OR BILL HISTORY</div><h3>Compare the leads, not the bills.</h3><p>Paste a second AWS-shaped JSON as a reference. Nimbus scans it with the same five rules and compares lead IDs with the inventory already shown. Neither input is verified or uploaded. The stated account and region must match; a disappeared lead does not prove savings or deletion.</p><label htmlFor="comparison-json">Reference inventory JSON<textarea id="comparison-json" value={comparisonText} onChange={e=>{setComparisonText(e.target.value);setComparisonInventory(null);setComparedAgainst('');setComparisonError('')}} rows={4} placeholder="Paste a second inventory in the example shape"/></label><button onClick={compareText} disabled={!comparisonText.trim()}>Compare local inputs ↗</button>{comparisonError&&<p role="alert">{comparisonError}</p>}{comparison&&<div className="local-diff-results"><button onClick={()=>download('nimbus-local-input-comparison.json',inventoryDiffReport(comparisonInventory!,inputInventory),'application/json')}>Download comparison JSON ↓</button><div className="local-diff-summary"><span>Reference: {comparison.previousCount} leads · {money(comparison.previousMonthlyUsd)}/mo rough estimate</span><span>Current: {comparison.currentCount} leads · {money(comparison.currentMonthlyUsd)}/mo rough estimate</span><strong>Difference: {comparison.differenceMonthlyUsd>=0?'+':''}{money(comparison.differenceMonthlyUsd)}/mo, not verified savings</strong></div><div className="diff-reconcile"><span>HOW THE ROUGH ESTIMATE CHANGED</span><div><b>New leads +{money(diffDetails!.addedUsd)}</b><b>No longer flagged -{money(diffDetails!.clearedUsd)}</b><b>Still flagged {diffDetails!.continuingDeltaUsd>=0?"+":""}{money(diffDetails!.continuingDeltaUsd)}</b></div><p>Net estimate difference: {diffDetails!.reconciledDeltaUsd>=0?"+":""}{money(diffDetails!.reconciledDeltaUsd)}/mo. This reconciles scanner outputs, not bills or realized savings.</p>{diffDetails!.rateChanges.length>0&&<p>Supplied rates differ: {diffDetails!.rateChanges.join(" · ")}. A rate change can alter estimates even with the same resource.</p>}{diffDetails!.chronology!=="later"&&<p>Capture order is {diffDetails!.chronology==="same"?"the same timestamp":"earlier in the current input"}. Do not interpret this as a chronological improvement.</p>}{diffDetails!.ongoing.some(x=>x.deltaUsd!==0)&&<details><summary>Still-flagged estimate changes</summary><ul>{diffDetails!.ongoing.filter(x=>x.deltaUsd!==0).map(x=><li key={x.id}>{x.id}: {money(x.referenceUsd)} → {money(x.currentUsd)} /mo</li>)}</ul></details>}</div><div className="local-diff-grid"><article><h4>New in current input ({comparison.added.length})</h4><p>{comparison.added.length?comparison.added.map(f=>f.resourceId).join(' · '):'None'}</p></article><article><h4>No longer flagged ({comparison.cleared.length})</h4><p>{comparison.cleared.length?comparison.cleared.map(f=>f.resourceId).join(' · '):'None'}</p></article><article><h4>Still flagged ({comparison.shared.length})</h4><p>{comparison.shared.length?comparison.shared.map(f=>f.resourceId).join(' · '):'None'}</p></article></div><small>Scan rules use each input's own capture date and supplied rates. Differing capture dates or rates can change estimates without any cloud change.</small></div>}</section>}{showRateLab&&<section className="rate-lab" aria-label="One-rate what-if"><div className="small-label">LOCAL WHAT-IF / ONE SUPPLIED RATE</div><h3>Change one assumption.</h3><p>Pick one rate from this input to see which lead estimates move. The finding cards, review decisions, actual bill and supplied JSON remain unchanged. This is not a verified price quote.</p><div className="rate-lab-controls"><label>INPUT RATE<select value={rateKey} onChange={e=>{setRateKey(e.target.value as RateKey);setTrialRate(null)}}>{Object.keys(inputInventory.rates).map(k=><option key={k} value={k}>{k}</option>)}</select></label><label>WHAT-IF RATE ($)<input type="number" min="0" max="1000000" step="0.0001" value={trialRate??inputInventory.rates[rateKey]} onChange={e=>setTrialRate(Math.max(0,Math.min(1_000_000,Number(e.target.value)||0)))}/></label></div><div className="rate-lab-summary"><span>Original {money(lab.originalUsd)}/mo</span><span>One-rate what-if {money(lab.alternativeUsd)}/mo</span><strong>Difference {lab.deltaUsd>=0?"+":""}{money(lab.deltaUsd)}/mo</strong></div>{lab.rows.length?<ul>{lab.rows.map(r=><li key={r.resourceId}><b>{r.resourceId}</b><span>{money(r.originalUsd)} → {money(r.alternativeUsd)} /mo</span></li>)}</ul>:<p>No lead estimate changes at this rate. This does not prove a resource is free.</p>}</section>}{showSensitivity&&<section className="sensitivity-panel" aria-label="Rate assumption sensitivity"><div className="small-label">WHAT-IF / INPUT RATES ONLY</div><h3>What if the rates differ?</h3><p>Scale every supplied rate together without changing the inventory or review decisions. This is a local sensitivity check, not a price quote, bill history, or forecast. Per-finding rounding can shift totals by cents.</p><label htmlFor="rate-sensitivity">Input rates at {ratePercent}%<input id="rate-sensitivity" type="range" min="50" max="150" step="10" value={ratePercent} onChange={e=>setRatePercent(Number(e.target.value))}/></label><div className="sensitivity-grid"><div><small>ORIGINAL CANDIDATE ESTIMATE</small><strong>{money(sensitivity.baseMonthlyUsd)}/mo</strong></div><div><small>SCALED CANDIDATE ESTIMATE</small><strong>{money(sensitivity.scenarioMonthlyUsd)}/mo</strong></div><div><small>ESTIMATE DIFFERENCE</small><strong>{sensitivity.deltaMonthlyUsd>=0?'+':''}{money(sensitivity.deltaMonthlyUsd)}/mo</strong></div></div><small>{sensitivity.baseCount} original leads · {sensitivity.scenarioCount} in this rate-only calculation. The actual finding cards and plan still show the original supplied rates.</small></section>}{showPriority&&<section className="priority-panel" aria-label="Open review queue"><div className="small-label">OPEN LEADS / REVIEW ORDER ONLY</div><h3>What to check first.</h3><p>Ordered by rule-level caution, then rough monthly estimate. Neither signal measures your business impact, and this is not an action queue.</p>{priority.length?<ol>{priority.map(row=><li key={row.id}><div><span>{row.caution.toUpperCase()} CAUTION · {label[row.kind]}</span><strong>{row.resourceId}</strong><small>{row.checks[0]}</small></div><b>{money(row.monthlyEstimateUsd)}/mo</b><button onClick={()=>openDetail(row.id)}>Inspect ↗</button></li>)}</ol>:<p>All leads have an in-browser decision. Recheck the plan; no AWS resource changed.</p>}</section>}{showAllocation&&<section className="allocation-panel" aria-label="Candidate estimates grouped by input tag"><div className="small-label">RESOURCE TAGS / CANDIDATE ESTIMATES ONLY</div><h3>See how candidates are tagged.</h3><p>Groups only findings by a tag in this input. This is not an allocation of an AWS bill, verified ownership, or Kubernetes cost.</p>{tagKeys.length?<><label>GROUP BY TAG<select value={selectedTag} onChange={e=>setAllocationKey(e.target.value)}>{tagKeys.map(k=><option key={k} value={k}>{k}</option>)}</select></label>{tagQuality&&<div className="tag-quality"><strong>{tagQuality.present}/{tagQuality.total} resource records carry this tag</strong><span>{money(tagQuality.candidateEstimateUsd)}/mo of candidate estimates have no value for this tag. An absent tag does not prove no owner.</span><details><summary>See {tagQuality.missingIds.length} missing or unavailable IDs</summary><p>{tagQuality.missingIds.join(' · ')||'None'}</p></details></div>}<div className="allocation-rows">{allocation.map(row=><article key={row.value}><strong>{row.value}</strong><span>{row.count} {row.count===1?'finding':'findings'}</span><b>{money(row.estimatedMonthlyUsd)}/mo</b><small>{row.resourceIds.join(' · ')}</small></article>)}</div></>:<p>No tags in this input. Candidate estimates cannot be grouped by an owner tag.</p>}</section>}{showCoverage&&<section className="coverage-panel" aria-label="Input coverage"><div className="small-label">INPUT COVERAGE / NOT A CONFIDENCE SCORE</div><h3>What the rules could inspect.</h3><p>Missing data stops some idle claims. A checked field is not proof that a resource is safe to remove.</p><div className="coverage-grid">{coverage.map(c=><article key={c.rule}><h4>{c.rule}</h4><strong>{c.evaluated-c.blocked}/{c.evaluated}</strong><span>with needed fields</span><small>{c.note}</small></article>)}</div></section>}{showPlan&&<section className="review-plan" aria-label="Review plan"><div className="small-label">HUMAN REVIEW / NO CLOUD WRITES</div><h3>A plan, not a delete button.</h3><p>{plan.approved.length} approved for further review · {plan.denied.length} denied · {plan.open.length} still open. Nothing is sent to AWS.</p><div className="check-progress">{checkProgress.done}/{checkProgress.total} checklist prompts self-marked across {findings.length} leads · {checkProgress.complete} fully marked. These marks are reminders, not verified evidence or permission to act.</div><div className="review-gates"><div><span className="small-label">LOCAL REVIEW GATES / NOT ENFORCEMENT</span><label>Flag approved items above a rough monthly estimate ($)<input type="number" min="0" step="1" value={itemReviewThreshold} onChange={e=>setItemReviewThreshold(Math.max(0,Number(e.target.value)||0))}/></label><strong>{gates.length?`${gates.length} approved ${gates.length===1?'item needs':'items need'} extra checks`:'No threshold or critical-caution flags in approved items'}</strong><p>A flag is a review reminder, not an account policy or a go-ahead to change AWS.</p></div>{gates.length>0&&<ul>{gates.map(g=><li key={g.id}><b>{g.resourceId}</b> {g.reasons.join(' ')}</li>)}</ul>}</div><div className="review-portability"><div className="small-label">LOCAL REVIEW HANDOFF / NO ACCOUNT SYNC</div><h4>Take the review with you.</h4><p>Download a JSON snapshot of these in-browser decisions, notes, stages and self-marked prompts. To restore, run the same inventory and paste the saved review JSON. It must match the exact scan inventory and lead IDs. Keep the file private: it includes the full inventory and your notes so Nimbus can match the exact input.</p><button onClick={()=>download("nimbus-local-review.json",reviewSession(inputInventory,findings,{decisions,notes,stages,checked}),"application/json")}>Download local review JSON ↓</button><label htmlFor="review-restore">Paste saved review JSON<textarea id="review-restore" rows={3} value={reviewJson} onChange={e=>{setReviewJson(e.target.value);setReviewRestoreMessage('')}} placeholder="Paste a previously downloaded local review JSON"/></label><button onClick={restoreReview} disabled={!reviewJson.trim()}>Restore matching review ↗</button>{reviewRestoreMessage&&<p role="status">{reviewRestoreMessage}</p>}</div><div className="plan-columns"><div><h4>Approved for review <span>{money(plan.estimatedMonthlyApproved)}/mo</span></h4>{plan.approved.length?plan.approved.map(f=><article key={f.id}><strong>{f.title}</strong><small>{f.resourceId}</small><p>{f.recommendation}</p><em>{f.risk}</em></article>):<p>No items in this plan yet. Approve a finding after reading its evidence.</p>}</div><div><h4>Before any future action</h4><ol><li>Confirm the live account, region, resource ID and owner.</li><li>Check current utilization, dependencies, actual bill and rollback.</li><li>Verify recoverability for volumes and snapshots.</li><li>Get separate human approval for any real write.</li></ol><button onClick={()=>download('nimbus-sample-review-plan.md',planMarkdown(findings,decisions,notes,sourceName,stages,checked),'text/markdown')}>Download review plan ↓</button></div></div></section>}{showAudit&&<section className="audit-panel" aria-label="Scan audit"><div className="small-label">INPUT INVENTORY / READ-ONLY</div><h3>What made the list. What did not.</h3><p>Every resource evaluated by these five rules, including the ones excluded. Built-in examples are synthetic; imported JSON is unverified local data, not a connected account.</p><div className="audit-summary">{audit.length} resources evaluated · {findings.length} flagged · {audit.length-findings.length} not flagged</div><div className="audit-gap-note">{gaps.missingEvidence} of {gaps.excluded} not-flagged records lack key rule evidence or a matching rate. Excluded means these checks did not flag them, not that they are safe or free.</div><button className="audit-download" onClick={()=>download('nimbus-full-audit.csv',auditCsv(audit,sourceName),'text/csv')}>Download full audit CSV ↓</button><div className="audit-controls"><label>SEARCH FULL INVENTORY<input type="search" value={auditQuery} onChange={e=>setAuditQuery(e.target.value)} placeholder="Resource ID, type, or exclusion reason"/></label><label>STATUS<select value={auditStatus} onChange={e=>setAuditStatus(e.target.value as AuditStatus)}><option value="all">All resources</option><option value="flagged">Flagged</option><option value="not flagged">Not flagged</option></select></label><span>{auditVisible.length} of {audit.length} shown</span></div><div className="audit-rows">{auditVisible.length===0?<p className="audit-empty">No resources match. Clear the search or status filter.</p>:auditVisible.map(row=><article key={row.resourceId}><div><small>{row.service}</small><strong>{row.resourceId}</strong></div><span className={row.status==='flagged'?'flagged':''}>{row.status}</span><p>{row.why}</p><small className="audit-next">NEXT EVIDENCE: {nextEvidence(row)}</small></article>)}</div></section>}{showInsights&&<section className="insights" aria-label="Sample cost picture"><div className="insights-heading"><span>THE COST PICTURE / INPUT ESTIMATES</span><h3>See the shape of the waste.</h3><p>These numbers total the scanner's candidate findings from the selected local inventory, not total cloud spend or a bill. Annualized values multiply rough monthly estimates by 12; they are not a forecast.</p></div><div className="insight-grid"><article><small>ANNUALIZED CANDIDATES</small><strong>{money(possible*12)}</strong><span>if every finding proved valid</span></article><article><small>ANNUALIZED PLAN</small><strong>{money(projected*12)}</strong><span>approved estimates, not realized savings</span></article><article><small>REVIEW PROGRESS</small><strong>{reviewed}/{findings.length}</strong><span>{findings.length-reviewed} decisions still open</span></article></div><div className="breakdown"><h4>By resource type</h4>{breakdown.map(([kind,amount])=><div key={kind}><span>{label[kind as Finding['kind']]}</span><div className="breakdown-track"><i style={{width:`${possible?amount/possible*100:0}%`}}/></div><b>{money(amount)}/mo</b></div>)}</div><div className="budget-compare"><label htmlFor="target">Compare candidates to a monthly review target ($)</label><input id="target" type="number" min="1" step="1" value={monthlyTarget} onChange={e=>setMonthlyTarget(Math.max(1,Number(e.target.value)||1))}/><p>{money(possible)} candidate total is {possible>=monthlyTarget?`${money(possible-monthlyTarget)} above`:`${money(monthlyTarget-possible)} below`} the review target. This is not an account budget alert.</p></div></section>}{lastDecision&&<div className="undo-strip" role="status">Decision updated in this browser only. <button onClick={undo}>Undo last decision</button></div>}<div className="cards">{visible.length===0?<div className="empty">{findings.length===0?'No candidates from these five checks. Open the scan audit to see why each resource was excluded; this is not proof of zero waste.':'No findings match. Clear filters or change your search.'}</div>:visible.map((f,i)=><article className={`finding kind-${f.kind}`} key={f.id}><div className="finding-top"><span className="kind-icon" aria-hidden="true"><Glyph name={f.kind}/></span><span className="kind-label">{label[f.kind]}</span><span className="finding-number">{String(findings.indexOf(f)+1).padStart(2,'0')}</span></div><h3>{f.title}</h3><p className="explanation">{f.explanation}</p><div className="resource">{f.resourceId}</div><div className="finding-bottom"><div className="card-cost"><small>{ruleRisk(f).toUpperCase()} CAUTION · ESTIMATED COST</small><strong>{money(f.estimatedMonthlyUsd)}<span> / month</span></strong></div><button className="inspect" onClick={()=>openDetail(f.id)}>Inspect evidence <span>↗</span></button></div><div className="decision-row"><button onClick={()=>decide(f,'approved')} aria-pressed={decisions[f.id]==='approved'} className={'approve '+(decisions[f.id]==='approved'?'chosen':'')}>{decisions[f.id]==='approved'?'✓ In plan':'Approve for plan'}</button><button onClick={()=>decide(f,'kept')} aria-pressed={decisions[f.id]==='kept'} className={'deny '+(decisions[f.id]==='kept'?'chosen':'')}>{decisions[f.id]==='kept'?'✓ Denied':'Deny'}</button></div></article>)}</div></section>
    <footer><span>NOT A LIVE AWS BILL</span><p><span className="asterisk">*</span> Prices are input assumptions, not verified rates. Findings are leads, not proof of waste. This scanner runs locally on built-in or pasted JSON only. It never calls AWS or deletes a resource.</p><span>BUILT FOR REVIEW, NOT GUESSWORK</span></footer>
    {active&&<div className="overlay" onClick={closeDetail}><aside className="drawer" role="dialog" onKeyDown={e=>{if(e.key==='Escape'){e.preventDefault();closeDetail()}if(e.key==='Tab'){const focusables=Array.from(e.currentTarget.querySelectorAll<HTMLElement>('button:not([disabled]),input:not([disabled]),textarea:not([disabled]),select:not([disabled]),a[href]'));const first=focusables[0],last=focusables[focusables.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}}} aria-modal="true" aria-labelledby="detail-title" onClick={e=>e.stopPropagation()}><button ref={closeRef} className="close" aria-label="Close details" onClick={closeDetail}>×</button><div className="small-label">RESOURCE EVIDENCE / {active.kind.toUpperCase()}</div><h2 id="detail-title">{active.title}</h2><div className="drawer-id">{active.resourceId}</div><div className="drawer-impact"><span>ESTIMATED MONTHLY COST</span><strong>{money(active.estimatedMonthlyUsd)}<small> / month</small></strong><p>Input-rate estimate, not a bill. Confirm the resource and owner before acting.</p></div><p className="drawer-summary">{active.explanation}</p><div className="estimate-breakdown"><div className="drawer-section-index">HOW THIS ESTIMATE WAS MADE</div><strong>{explainEstimate(active,inputInventory).formula}</strong><small>{explainEstimate(active,inputInventory).unitRate}</small><p>{explainEstimate(active,inputInventory).assumption}</p><p>{explainEstimate(active,inputInventory).coverage}</p></div>{metricEvidence(active,inputInventory).length>0&&<div className="metric-evidence"><div className="drawer-section-index">SUPPLIED SAMPLES / NOT DATED OR LIVE</div><p>Each bar is one of the 14 values in this input. Dates and collection source are not verified. Threshold values and these samples do not prove a resource is idle. Bars share a scale within each strip; no threshold line is drawn.</p>{metricEvidence(active,inputInventory).map(row=><div className="metric-row" key={row.label}><strong>{row.label}</strong><span>{row.description}</span><div className="metric-bars" role="img" aria-label={`${row.label}: 14 supplied values; threshold ${row.threshold} ${row.unit}`}>{row.values.map((value,j)=><i key={j} title={`Sample ${j+1}: ${value} ${row.unit}`} style={{height:`${Math.max(4,Math.min(100,value/Math.max(row.threshold*1.2,...row.values)*100))}%`}}/>)}</div><small>Min {Math.min(...row.values).toLocaleString()} · Max {Math.max(...row.values).toLocaleString()} {row.unit} · Threshold {row.threshold.toLocaleString()} {row.unit}</small></div>)}</div>}<div className="drawer-block"><div className="drawer-section-index">01 / EVIDENCE</div><h4>What the scan saw</h4><ul>{active.evidence.map((line,i)=><li key={i}>{line}</li>)}</ul></div><div className="drawer-block"><div className="drawer-section-index">02 / JUDGMENT</div><h4>Before you do anything</h4><p>{recommendation(active)}</p><div className="risk-panel"><span>WHAT COULD GO WRONG</span><p className="risk">{active.risk}</p></div></div><div className="review-stage-control"><label htmlFor="review-stage">LOCAL INVESTIGATION STAGE</label><select id="review-stage" value={stages[active.id]||"new"} onChange={e=>setStages(old=>({...old,[active.id]:e.target.value as ReviewStage}))}><option value="new">New</option><option value="investigating">Investigating</option><option value="on-hold">On hold</option></select><small>For your local triage only. Separate from approve or deny and never synced or sent to AWS.</small></div><div className="review-checklist"><div className="drawer-section-index">SELF-MARKED REVIEW PROMPTS / NOT VERIFIED</div>{reviewChecks.map(c=><label key={c.id}><input type="checkbox" checked={checked[active.id]?.includes(c.id)||false} onChange={e=>setChecked(old=>({...old,[active.id]:e.target.checked?[...new Set([...(old[active.id]||[]),c.id])]:[...(old[active.id]||[])].filter(x=>x!==c.id)}))}/>{c.label}</label>)}<small>These marks stay in this browser until reload. They do not prove a check occurred or approve any AWS change.</small></div><div className="review-note"><label htmlFor="review-note">Private review note (this page only)</label><textarea id="review-note" value={notes[active.id]||''} onChange={e=>setNotes(old=>({...old,[active.id]:e.target.value}))} placeholder="What should be checked before acting?"/><small>Included in exports. Not sent to AWS or saved after reload.</small></div><div className="drawer-note">{localInventory?'LOCAL JSON':'SAMPLE MODE'} · Approve adds this estimate to your in-browser plan. It never changes a cloud resource.</div><div className="drawer-actions"><button onClick={()=>{decide(active,'approved');closeDetail()}}>Approve for plan</button><button onClick={()=>{decide(active,'kept');closeDetail()}}>Deny finding</button></div></aside></div>}
  </main>
}
function Setup({scenario,onScenario,onImport,jsonText,onJsonText,importMessage,localInventory,onBack,onRun}:{scenario:Scenario;onScenario:(s:Scenario)=>void;onImport:()=>void;jsonText:string;onJsonText:(s:string)=>void;importMessage:string;localInventory:Inventory|null;onBack:()=>void;onRun:()=>void}){
  return <main className="setup-page">
    <header className="setup-nav"><button onClick={onBack}>← Nimbus</button><span>01 / SETUP</span><span className="setup-nav-status">LOCAL MODE · NO AWS ACCESS</span></header>
    <div className="setup-grid"><section className="setup-intro">
      <div className="setup-eyebrow"><span>✳</span> LET'S TAKE A LOOK</div>
      <h1>Your cloud, <em>less cluttered.</em></h1>
      <p>Start with a sample inventory or your own AWS-shaped JSON. Nimbus runs the actual read-only scan rules on AWS-shaped data, then shows the resource, evidence, rough cost, and risk behind every finding.</p>
      <div className="setup-steps"><div className="current"><b>01</b><span>Choose an inventory</span></div><div><b>02</b><span>Run read-only checks</span></div><div><b>03</b><span>Review each finding</span></div></div>
      <div className="setup-aside">Nothing in this flow signs in to AWS, touches a resource, or changes a bill.</div><div className="setup-illustration" aria-hidden="true"><span className="orbit orbit-a"/><span className="orbit orbit-b"/><span className="orbit orbit-c"/><div className="setup-illustration-center">✳</div><small>FIND THE SIGNAL<br/>KEEP THE SAY</small></div>
    </section><section className="setup-panel" aria-label="Sample scan setup">
      <div className="setup-panel-head"><span>SCAN CONFIGURATION</span><b>01 / 03</b></div><div className="setup-progress" aria-label="Step 1 of 3"><i/><i/><i/></div>
      <h2>Start with a sample.</h2><p>Use a built-in example or a pasted JSON without connecting an account.</p>
      <div className="sample-source"><span className="source-icon"><Glyph name="instance" size={23}/></span><div><strong>Synthetic AWS inventory</strong><small>2 EC2 instances · 2 EBS volumes · 2 IPs · 1 load balancer · 1 snapshot</small></div><span className="source-check">✓</span></div><fieldset className="scenario-choices"><legend>CHOOSE A SAMPLE SITUATION</legend>{(Object.keys(scenarios) as Scenario[]).map(key=><label key={key} className={scenario===key?'selected':''}><input type="radio" name="scenario" value={key} checked={scenario===key} onChange={()=>onScenario(key)}/><span><strong>{scenarios[key].title}</strong><small>{scenarios[key].description}</small></span></label>)}</fieldset>
      <div className="local-upload"><label htmlFor="inventory-json">Or paste an AWS-shaped JSON inventory</label><textarea id="inventory-json" value={jsonText} onChange={e=>onJsonText(e.target.value)} placeholder="Paste JSON matching the bundled fixture shape" spellCheck={false} rows={4}/><button type="button" onClick={onImport} disabled={!jsonText.trim()}>Use pasted JSON</button><small>No credentials, AWS connection or upload. Paste only data you are permitted to inspect. Max 1 MB. This input is not a verified AWS bill. For the required shape, download the example below.</small>{importMessage&&<p role="status">{importMessage}</p>}</div><div className="setup-field"><label htmlFor="region-choice">Region in {localInventory?'local JSON':'sample'}</label><div className="setup-region">{localInventory?.region||'US East (N. Virginia) · us-east-1'}</div><small>{localInventory?'Read from the chosen JSON. Not verified against AWS.':"Fixed to the fixture's region; no cloud account is queried."}</small></div>
      <button className="example-download" onClick={()=>{const blob=new Blob([JSON.stringify(fixture,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='nimbus-example-inventory.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),5000)}}>Download example JSON ↓</button><div className="setup-options"><span>CHECKS INCLUDED</span><div><b>✓</b> Compute and storage <small>Idle EC2 · unattached EBS</small></div><div><b>✓</b> Network <small>Unused IPv4 · load balancer</small></div><div><b>✓</b> Backups <small>Old snapshot candidates</small></div></div>
      <button className="setup-run" onClick={onRun}>{localInventory?'Run local JSON scan':'Run sample scan'} <span>↗</span></button><div className="setup-foot">Read-only rules. Input rate assumptions. Every finding waits for your review.</div>
    </section></div>
    <footer className="setup-footer">NIMBUS <span>FIND THE LEAKS. KEEP THE CONTROL.</span></footer>
  </main>;
}
function Landing({openDashboard,openAgent}:{openDashboard:()=>void;openAgent:()=>void}){
 return <main className="new-landing"><header className="new-nav"><div className="new-logo"><img className="brand-mascot" alt="" src="data:image/png;base64,"/>Nimbus<span className="logo-trademark">®</span></div><nav><span>THE IDEA</span><span>THE FINDINGS</span><button onClick={openDashboard}>Set up scan <b>↗</b></button></nav></header>
 <section className="new-hero"><div className="new-kicker"><span className="tiny-star">✳</span> AN APPROVAL-FIRST CLOUD COST AGENT <span className="tiny-star">✳</span></div><h1>Goodbye, cloud<br/><em>cost clutter.</em></h1><p>Find the idle things quietly eating your budget. See the proof, weigh the savings, and decide what stays. Nothing goes away without you.</p><button className="new-primary" onClick={openDashboard}>Set up your scan <span>↗</span></button><button className="trueforge-entry" onClick={openAgent}>Open TrueForge agent ↗</button><div className="new-hero-note">A little less waste. A lot more clarity.</div>
 <div className="sky-scene" aria-hidden="true"><div className="sun-glow"/><div className="cloud cloud-one"/><div className="cloud cloud-two"/><div className="cloud cloud-three"/><div className="cloud cloud-four"/><div className="hill hill-back"/><div className="hill hill-front"/><div className="ground-text">LESS WASTE. MORE ROOM TO BUILD.</div></div></section>
 <section className="new-story"><div className="story-intro"><span>WHY WE MADE THIS</span><h2>The good stuff should<br/>get your budget.</h2><p>Not a disk nobody uses. Not a server running for no reason. We turn the overlooked parts of your cloud into a clear list of choices.</p></div><div className="story-row"><article><span>01</span><h3>Find it.</h3><p>Scan AWS-shaped inventory for the usual suspects. Every finding points to a resource.</p></article><article><span>02</span><h3>Understand it.</h3><p>Plain words, evidence and a rough monthly cost. No mystery score.</p></article><article><span>03</span><h3>You decide.</h3><p>Approve or deny each one. Nothing changes outside the demo.</p></article></div></section><section className="new-last"><span>READY FOR THE CLEARER PICTURE?</span><h2>See where it goes.<br/><em>Keep what matters.</em></h2><button onClick={openDashboard}>Explore findings ↗</button><p>SYNTHETIC FIXTURE DATA · ESTIMATES ONLY · NO LIVE AWS ACCESS</p></section></main>
}
export {App as NimbusApp};
